import { resolveProductDatabasePath } from './ProductControlPlane';
const openProductDatabase = (path: string) => path;
const choose = (canonical: string, alternate: string, flag: boolean) => flag ? canonical : alternate;
export const makeStore = (stateDir: string, alternate: string, flag: boolean) => openProductDatabase(choose(resolveProductDatabasePath(stateDir), alternate, flag));
